import { createFilesystemStorage } from "./backends/filesystem.js";
import { createIndexedDbStorage } from "./backends/indexeddb.js";
import {
  createPostMessageAdapter,
  hasTauriRuntime,
  isInIframe,
} from "./bridge/post-message-adapter.js";
import {
  detectPlatform,
  loadConfig,
  mergeConfig,
  resolveBackend,
} from "./config.js";
import type {
  ChromaFsConfig,
  CreateStorageOptions,
  FileEntry,
  RemoveOptions,
  Storage,
} from "./types.js";

export class ChromaFs implements Storage {
  private readonly storage: Storage;

  constructor(storage: Storage) {
    this.storage = storage;
  }

  static async create(options: CreateStorageOptions = {}): Promise<ChromaFs> {
    const storage = await createChromaFsStorage(options);
    return new ChromaFs(storage);
  }

  readFile(path: string): Promise<Uint8Array> {
    return this.storage.readFile(path);
  }

  readText(path: string): Promise<string> {
    return this.storage.readText(path);
  }

  writeFile(path: string, data: string | Uint8Array): Promise<void> {
    return this.storage.writeFile(path, data);
  }

  delete(path: string): Promise<void> {
    return this.storage.delete(path);
  }

  exists(path: string): Promise<boolean> {
    return this.storage.exists(path);
  }

  list(path?: string): Promise<FileEntry[]> {
    return this.storage.list(path);
  }

  mkdir(path: string): Promise<void> {
    return this.storage.mkdir(path);
  }

  rmdir(path: string, options?: RemoveOptions): Promise<void> {
    return this.storage.rmdir(path, options);
  }

  stat(path: string): Promise<FileEntry | null> {
    return this.storage.stat(path);
  }
}

export async function createChromaFs(
  options: CreateStorageOptions = {},
): Promise<ChromaFs> {
  return ChromaFs.create(options);
}

async function createChromaFsStorage(options: CreateStorageOptions): Promise<Storage> {
  const config = await resolveChromaFsConfig(options);
  const platform = detectPlatform();
  const backend = resolveBackend(config, platform);

  if (options.adapter) {
    return createFilesystemStorage({
      basePath: config.storage.basePath ?? "./data",
      adapter: options.adapter,
    });
  }

  if (backend === "filesystem") {
    if (isInIframe()) {
      return createFilesystemStorage({
        basePath: config.storage.basePath ?? "./data",
        adapter: createPostMessageAdapter(),
      });
    }

    if (hasTauriRuntime() && !isInIframe()) {
      return createFilesystemStorage({
        basePath: config.storage.basePath ?? "./data",
      });
    }

    throw new Error(
      "Filesystem backend requires Chroma Desktop (postMessage bridge) or a Tauri host with @tauri-apps/plugin-fs.",
    );
  }

  return createIndexedDbStorage({
    dbName: config.storage.indexedDb?.dbName ?? "chroma-fs",
    storeName: config.storage.indexedDb?.storeName ?? "files",
  });
}

async function resolveChromaFsConfig(
  options: CreateStorageOptions,
): Promise<ChromaFsConfig> {
  if (options.configPath) {
    const loaded = await loadConfig(options.configPath);
    return options.config
      ? mergeConfig({ storage: { ...loaded.storage, ...options.config.storage } })
      : loaded;
  }

  if (options.config) {
    return mergeConfig(options.config);
  }

  try {
    return await loadConfig("chroma-fs.json");
  } catch {
    return mergeConfig();
  }
}
