import { isInIframe } from "./bridge/post-message-adapter.js";
import type { ChromaFsConfig, PlatformKind, StorageBackendType } from "./types.js";

const DEFAULT_BASE_PATH = "./data";
const DEFAULT_DB_NAME = "chroma-fs";
const DEFAULT_STORE_NAME = "files";

const DEFAULT_CONFIG: ChromaFsConfig = {
  storage: {
    basePath: DEFAULT_BASE_PATH,
    indexedDb: {
      dbName: DEFAULT_DB_NAME,
      storeName: DEFAULT_STORE_NAME,
    },
  },
};

export function mergeConfig(
  partial?: Partial<ChromaFsConfig>,
): ChromaFsConfig {
  const storagePartial = partial?.storage;

  return {
    storage: {
      basePath:
        typeof storagePartial?.basePath === "string"
          ? storagePartial.basePath
          : DEFAULT_BASE_PATH,
      ...(storagePartial?.backend ? { backend: storagePartial.backend } : {}),
      indexedDb: {
        dbName:
          storagePartial?.indexedDb?.dbName ??
          DEFAULT_CONFIG.storage.indexedDb?.dbName ??
          "chroma-fs",
        storeName:
          storagePartial?.indexedDb?.storeName ??
          DEFAULT_CONFIG.storage.indexedDb?.storeName ??
          "files",
      },
    },
  };
}

export function parseConfig(raw: unknown): ChromaFsConfig {
  if (!raw || typeof raw !== "object") {
    throw new Error("Invalid Chroma-Fs config: expected a JSON object.");
  }

  const candidate = raw as Record<string, unknown>;
  const storage = candidate.storage;

  if (!storage || typeof storage !== "object") {
    throw new Error("Invalid Chroma-Fs config: missing storage section.");
  }

  const storageRecord = storage as Record<string, unknown>;
  const backend = storageRecord.backend;

  if (
    backend !== undefined &&
    backend !== "indexeddb" &&
    backend !== "filesystem"
  ) {
    throw new Error(
      'Invalid Chroma-Fs config: storage.backend must be "indexeddb" or "filesystem".',
    );
  }

  const indexedDb = storageRecord.indexedDb;
  if (indexedDb !== undefined && typeof indexedDb !== "object") {
    throw new Error("Invalid Chroma-Fs config: storage.indexedDb must be an object.");
  }

  const indexedDbRecord =
    indexedDb && typeof indexedDb === "object"
      ? (indexedDb as Record<string, unknown>)
      : null;

  const parsedIndexedDb: ChromaFsConfig["storage"]["indexedDb"] = indexedDbRecord
    ? {
        ...(typeof indexedDbRecord.dbName === "string"
          ? { dbName: indexedDbRecord.dbName }
          : {}),
        ...(typeof indexedDbRecord.storeName === "string"
          ? { storeName: indexedDbRecord.storeName }
          : {}),
      }
    : DEFAULT_CONFIG.storage.indexedDb;

  return mergeConfig({
    storage: {
      ...(backend ? { backend: backend as StorageBackendType } : {}),
      ...(typeof storageRecord.basePath === "string"
        ? { basePath: storageRecord.basePath }
        : {}),
      ...(parsedIndexedDb ? { indexedDb: parsedIndexedDb } : {}),
    },
  });
}

export async function loadConfig(configPath = "chroma-fs.json"): Promise<ChromaFsConfig> {
  const response = await fetch(configPath, { cache: "no-store" });

  if (!response.ok) {
    throw new Error(`Unable to load Chroma-Fs config from ${configPath}.`);
  }

  const raw = (await response.json()) as unknown;
  return parseConfig(raw);
}

export function detectPlatform(): PlatformKind {
  if (typeof window === "undefined") {
    return "static";
  }

  const globals = window as Window & {
    __TAURI__?: unknown;
    __TAURI_INTERNALS__?: unknown;
  };

  if (globals.__TAURI__ || globals.__TAURI_INTERNALS__) {
    return "desktop";
  }

  // Chroma Desktop hosts apps in a cross-origin iframe without Tauri globals.
  if (isInIframe()) {
    return "desktop";
  }

  return "static";
}

export function resolveBackend(
  config: ChromaFsConfig,
  platform: PlatformKind,
): StorageBackendType {
  if (config.storage.backend) {
    return config.storage.backend;
  }

  return platform === "desktop" ? "filesystem" : "indexeddb";
}

export function defaultConfig(): ChromaFsConfig {
  return mergeConfig();
}
