import type { RemoveOptions, TauriDirEntry, TauriFileStat, TauriFsAdapter } from "../types.js";

const CHANNEL = "chroma-fs";

interface BridgeRequest {
  channel: typeof CHANNEL;
  id: string;
  op: string;
  args: Record<string, unknown>;
}

interface BridgeResponse {
  channel: typeof CHANNEL;
  id: string;
  ok: boolean;
  result?: unknown;
  error?: string;
}

let requestCounter = 0;

function nextId(): string {
  requestCounter += 1;
  return `${Date.now()}-${requestCounter}`;
}

function bytesToBase64(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }
  return btoa(binary);
}

function base64ToBytes(base64: string): Uint8Array {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

function getTargetWindow(): Window {
  if (typeof window === "undefined") {
    throw new Error("postMessage bridge requires a browser environment.");
  }
  return window.parent;
}

export function createPostMessageAdapter(): TauriFsAdapter {
  const pending = new Map<
    string,
    { resolve: (value: unknown) => void; reject: (error: Error) => void }
  >();

  if (typeof window !== "undefined") {
    window.addEventListener("message", (event) => {
      const data = event.data as BridgeResponse | undefined;
      if (!data || data.channel !== CHANNEL || !data.id) {
        return;
      }

      const handler = pending.get(data.id);
      if (!handler) {
        return;
      }

      pending.delete(data.id);
      if (data.ok) {
        handler.resolve(data.result);
      } else {
        handler.reject(new Error(data.error ?? "Chroma-Fs bridge request failed."));
      }
    });
  }

  function send<T>(op: string, args: Record<string, unknown> = {}): Promise<T> {
    const id = nextId();
    const message: BridgeRequest = { channel: CHANNEL, id, op, args };

    return new Promise<T>((resolve, reject) => {
      pending.set(id, {
        resolve: (value) => resolve(value as T),
        reject,
      });

      try {
        getTargetWindow().postMessage(message, "*");
      } catch (error) {
        pending.delete(id);
        reject(error instanceof Error ? error : new Error(String(error)));
      }
    });
  }

  return {
    async readFile(path) {
      const base64 = await send<string>("readFile", { path });
      return base64ToBytes(base64);
    },

    async readTextFile(path) {
      return send<string>("readTextFile", { path });
    },

    async writeFile(path, data) {
      await send<void>("writeFile", { path, data: bytesToBase64(data) });
    },

    async writeTextFile(path, data) {
      await send<void>("writeTextFile", { path, data });
    },

    async remove(path, options?: RemoveOptions) {
      await send<void>("remove", {
        path,
        recursive: options?.recursive ?? false,
      });
    },

    async exists(path) {
      return send<boolean>("exists", { path });
    },

    async readDir(path) {
      return send<TauriDirEntry[]>("readDir", { path });
    },

    async mkdir(path, options) {
      await send<void>("mkdir", {
        path,
        recursive: options?.recursive ?? false,
      });
    },

    async stat(path) {
      return send<TauriFileStat | null>("stat", { path });
    },
  };
}

export function isInIframe(): boolean {
  if (typeof window === "undefined") {
    return false;
  }

  try {
    return window.parent !== window;
  } catch {
    return true;
  }
}

export function hasTauriRuntime(): boolean {
  if (typeof window === "undefined") {
    return false;
  }

  const globals = window as Window & {
    __TAURI__?: unknown;
    __TAURI_INTERNALS__?: unknown;
  };

  return Boolean(globals.__TAURI__ || globals.__TAURI_INTERNALS__);
}
