import type { TauriDirEntry, TauriFileStat, TauriFsAdapter } from "../types.js";
import { normalizePath } from "../path.js";

type TauriFsModule = typeof import("@tauri-apps/plugin-fs");

function resolveRelativePath(basePath: string, path: string): string {
  const normalizedBase = normalizePath(basePath.replace(/^\.\//, ""));
  const normalizedPath = normalizePath(path);
  return normalizedBase
    ? normalizedPath
      ? `${normalizedBase}/${normalizedPath}`
      : normalizedBase
    : normalizedPath;
}

async function loadTauriFs(): Promise<TauriFsModule> {
  try {
    return await import("@tauri-apps/plugin-fs");
  } catch {
    throw new Error(
      "Filesystem backend requires @tauri-apps/plugin-fs. Install it in the host app and enable the fs plugin in Tauri.",
    );
  }
}

export async function createDefaultTauriFsAdapter(
  basePath = "./data",
): Promise<TauriFsAdapter> {
  const fs = await loadTauriFs();
  const options = { baseDir: fs.BaseDirectory.AppLocalData };

  const resolve = (path: string) => resolveRelativePath(basePath, path);

  return {
    async readFile(path: string) {
      return fs.readFile(resolve(path), options);
    },

    async readTextFile(path: string) {
      return fs.readTextFile(resolve(path), options);
    },

    async writeFile(path: string, data: Uint8Array) {
      await fs.writeFile(resolve(path), data, options);
    },

    async writeTextFile(path: string, data: string) {
      await fs.writeTextFile(resolve(path), data, options);
    },

    async remove(path: string, removeOptions?: { recursive?: boolean }) {
      await fs.remove(resolve(path), {
        ...options,
        recursive: removeOptions?.recursive ?? false,
      });
    },

    async exists(path: string) {
      return fs.exists(resolve(path), options);
    },

    async readDir(path: string) {
      const entries = await fs.readDir(resolve(path), options);
      return entries.map((entry) => mapDirEntry(entry));
    },

    async mkdir(path: string, mkdirOptions?: { recursive?: boolean }) {
      await fs.mkdir(resolve(path), {
        ...options,
        recursive: mkdirOptions?.recursive ?? false,
      });
    },

    async stat(path: string) {
      try {
        const stat = await fs.stat(resolve(path), options);
        return mapStat(stat);
      } catch {
        return null;
      }
    },
  };
}

function mapDirEntry(entry: {
  name: string;
  isDirectory: boolean;
  isFile: boolean;
}): TauriDirEntry {
  return {
    name: entry.name,
    isDirectory: entry.isDirectory,
    isFile: entry.isFile,
  };
}

function mapStat(stat: {
  isDirectory: boolean;
  isFile: boolean;
  size: number;
  mtime?: Date | null;
}): TauriFileStat {
  return {
    isDirectory: stat.isDirectory,
    isFile: stat.isFile,
    size: stat.size,
    mtime: stat.mtime ? stat.mtime.getTime() : null,
  };
}
