import {
  baseName,
  childPath,
  directoryPrefix,
  normalizePath,
  parentPath,
  toBytes,
  toText,
} from "../path.js";
import type { FileEntry, FileKind, Storage } from "../types.js";

interface StoredRecord {
  kind: FileKind;
  content?: Uint8Array;
  modifiedAt: number;
  size: number;
}

interface IndexedDbBackendOptions {
  dbName: string;
  storeName: string;
}

export class IndexedDbStorage implements Storage {
  private readonly dbName: string;
  private readonly storeName: string;
  private dbPromise: Promise<IDBDatabase> | null = null;

  constructor(options: IndexedDbBackendOptions) {
    this.dbName = options.dbName;
    this.storeName = options.storeName;
  }

  async readFile(path: string): Promise<Uint8Array> {
    const record = await this.getRecord(path);

    if (!record || record.kind !== "file") {
      throw new Error(`File not found: ${normalizePath(path)}`);
    }

    return record.content ? new Uint8Array(record.content) : new Uint8Array();
  }

  async readText(path: string): Promise<string> {
    const bytes = await this.readFile(path);
    return toText(bytes);
  }

  async writeFile(path: string, data: string | Uint8Array): Promise<void> {
    const normalizedPath = normalizePath(path);
    await this.ensureParentDirectories(normalizedPath);

    const content = toBytes(data);
    await this.putRecord(normalizedPath, {
      kind: "file",
      content,
      modifiedAt: Date.now(),
      size: content.byteLength,
    });
  }

  async delete(path: string): Promise<void> {
    const normalizedPath = normalizePath(path);
    const record = await this.getRecord(normalizedPath);
    const children = await this.list(normalizedPath);

    if (!record) {
      if (children.length > 0) {
        throw new Error(`Directory not empty: ${normalizedPath}`);
      }
      return;
    }

    if (record.kind === "directory" && children.length > 0) {
      throw new Error(`Directory not empty: ${normalizedPath}`);
    }

    await this.deleteRecord(normalizedPath);
  }

  async exists(path: string): Promise<boolean> {
    const record = await this.getRecord(path);
    return record != null;
  }

  async list(path = ""): Promise<FileEntry[]> {
    const normalizedPath = normalizePath(path);
    const prefix = directoryPrefix(normalizedPath);
    const records = await this.getAllRecords();
    const entries = new Map<string, FileEntry>();

    for (const [recordPath, record] of records) {
      if (prefix && !recordPath.startsWith(prefix)) {
        continue;
      }

      const relativePath = prefix ? recordPath.slice(prefix.length) : recordPath;
      if (!relativePath) {
        continue;
      }

      const slashIndex = relativePath.indexOf("/");
      const name = slashIndex === -1 ? relativePath : relativePath.slice(0, slashIndex);

      if (!name || entries.has(name)) {
        continue;
      }

      const entryPath = childPath(normalizedPath, name);
      const directRecord = records.get(entryPath);

      if (directRecord) {
        entries.set(name, this.toEntry(name, entryPath, directRecord));
        continue;
      }

      entries.set(name, {
        name,
        path: entryPath,
        kind: "directory",
      });
    }

    return [...entries.values()].sort((left, right) =>
      left.name.localeCompare(right.name),
    );
  }

  async mkdir(path: string): Promise<void> {
    const normalizedPath = normalizePath(path);
    if (!normalizedPath) {
      throw new Error("Cannot create the root directory.");
    }

    if (await this.exists(normalizedPath)) {
      const record = await this.getRecord(normalizedPath);
      if (record?.kind === "file") {
        throw new Error(`Path already exists as a file: ${normalizedPath}`);
      }
      return;
    }

    await this.ensureParentDirectories(normalizedPath);
    await this.putRecord(normalizedPath, {
      kind: "directory",
      modifiedAt: Date.now(),
      size: 0,
    });
  }

  async rmdir(path: string, options?: { recursive?: boolean }): Promise<void> {
    const normalizedPath = normalizePath(path);
    const record = await this.getRecord(normalizedPath);

    if (!record) {
      return;
    }

    if (record.kind !== "directory") {
      throw new Error(`Not a directory: ${normalizedPath}`);
    }

    const children = await this.list(normalizedPath);
    if (children.length > 0 && !options?.recursive) {
      throw new Error(`Directory not empty: ${normalizedPath}`);
    }

    if (options?.recursive) {
      for (const child of children) {
        if (child.kind === "directory") {
          await this.rmdir(child.path, { recursive: true });
        } else {
          await this.delete(child.path);
        }
      }
    }

    await this.deleteRecord(normalizedPath);
  }

  async stat(path: string): Promise<FileEntry | null> {
    const normalizedPath = normalizePath(path);
    const record = await this.getRecord(normalizedPath);

    if (!record) {
      return null;
    }

    return this.toEntry(baseName(normalizedPath), normalizedPath, record);
  }

  get databaseName(): string {
    return this.dbName;
  }

  async close(): Promise<void> {
    if (!this.dbPromise) {
      return;
    }

    const db = await this.dbPromise;
    db.close();
    this.dbPromise = null;
  }

  private toEntry(name: string, path: string, record: StoredRecord): FileEntry {
    return {
      name,
      path,
      kind: record.kind,
      ...(record.kind === "file" ? { size: record.size } : {}),
      modifiedAt: record.modifiedAt,
    };
  }

  private async ensureParentDirectories(path: string): Promise<void> {
    const parent = parentPath(path);
    if (!parent || (await this.exists(parent))) {
      return;
    }

    await this.ensureParentDirectories(parent);
    await this.putRecord(parent, {
      kind: "directory",
      modifiedAt: Date.now(),
      size: 0,
    });
  }

  private openDb(): Promise<IDBDatabase> {
    if (this.dbPromise) {
      return this.dbPromise;
    }

    this.dbPromise = new Promise((resolve, reject) => {
      const request = indexedDB.open(this.dbName, 1);

      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains(this.storeName)) {
          db.createObjectStore(this.storeName);
        }
      };

      request.onsuccess = () => resolve(request.result);
      request.onerror = () =>
        reject(request.error ?? new Error("Unable to open IndexedDB."));
    });

    return this.dbPromise;
  }

  private async withStore<T>(
    mode: IDBTransactionMode,
    run: (store: IDBObjectStore) => IDBRequest<T> | Promise<T>,
  ): Promise<T> {
    const db = await this.openDb();

    return new Promise((resolve, reject) => {
      const transaction = db.transaction(this.storeName, mode);
      const store = transaction.objectStore(this.storeName);
      const result = run(store);

      if (result instanceof Promise) {
        result.then(resolve).catch(reject);
        return;
      }

      let value: T;
      result.onsuccess = () => {
        value = result.result as T;
        if (mode === "readonly") {
          resolve(value);
        }
      };
      transaction.oncomplete = () => {
        if (mode === "readwrite") {
          resolve(value);
        }
      };
      result.onerror = () =>
        reject(result.error ?? new Error("IndexedDB request failed."));
      transaction.onerror = () =>
        reject(transaction.error ?? new Error("IndexedDB transaction failed."));
    });
  }

  private async getRecord(path: string): Promise<StoredRecord | null> {
    const normalizedPath = normalizePath(path);
    const record = await this.withStore("readonly", (store) =>
      store.get(normalizedPath),
    );
    return (record as StoredRecord | undefined) ?? null;
  }

  private async putRecord(path: string, record: StoredRecord): Promise<void> {
    const normalizedPath = normalizePath(path);
    await this.withStore("readwrite", (store) => store.put(record, normalizedPath));
  }

  private async deleteRecord(path: string): Promise<void> {
    const normalizedPath = normalizePath(path);
    await this.withStore("readwrite", (store) => store.delete(normalizedPath));
  }

  private async getAllRecords(): Promise<Map<string, StoredRecord>> {
    const db = await this.openDb();

    return new Promise((resolve, reject) => {
      const transaction = db.transaction(this.storeName, "readonly");
      const store = transaction.objectStore(this.storeName);
      const keysRequest = store.getAllKeys();
      const valuesRequest = store.getAll();

      valuesRequest.onsuccess = () => {
        const keys = keysRequest.result as string[];
        const values = valuesRequest.result as StoredRecord[];
        const records = new Map<string, StoredRecord>();

        for (let index = 0; index < keys.length; index += 1) {
          const key = String(keys[index]);
          const value = values[index];
          if (value) {
            records.set(key, value);
          }
        }

        resolve(records);
      };

      keysRequest.onerror = () =>
        reject(keysRequest.error ?? new Error("IndexedDB request failed."));
      valuesRequest.onerror = () =>
        reject(valuesRequest.error ?? new Error("IndexedDB request failed."));
      transaction.onerror = () =>
        reject(transaction.error ?? new Error("IndexedDB transaction failed."));
    });
  }
}

export function createIndexedDbStorage(options: IndexedDbBackendOptions): Storage {
  return new IndexedDbStorage(options);
}
