const LEADING_SLASHES = /^\/+/;
const TRAILING_SLASHES = /\/+$/;

export function normalizePath(path: string): string {
  const trimmed = path.trim().replace(/\\/g, "/");
  if (!trimmed || trimmed === ".") {
    return "";
  }

  const segments = trimmed
    .split("/")
    .filter((segment) => segment.length > 0 && segment !== ".");

  const stack: string[] = [];
  for (const segment of segments) {
    if (segment === "..") {
      stack.pop();
      continue;
    }
    stack.push(segment);
  }

  return stack.join("/");
}

export function joinPath(base: string, path: string): string {
  const normalizedBase = normalizePath(base);
  const normalizedPath = normalizePath(path);

  if (!normalizedBase) {
    return normalizedPath;
  }

  if (!normalizedPath) {
    return normalizedBase;
  }

  return `${normalizedBase}/${normalizedPath}`;
}

export function parentPath(path: string): string {
  const normalized = normalizePath(path);
  const index = normalized.lastIndexOf("/");
  return index === -1 ? "" : normalized.slice(0, index);
}

export function baseName(path: string): string {
  const normalized = normalizePath(path);
  const index = normalized.lastIndexOf("/");
  return index === -1 ? normalized : normalized.slice(index + 1);
}

export function childPath(parent: string, name: string): string {
  return joinPath(parent, name);
}

export function isDirectChild(parent: string, candidate: string): boolean {
  const normalizedParent = normalizePath(parent);
  const normalizedCandidate = normalizePath(candidate);

  if (normalizedParent === normalizedCandidate) {
    return false;
  }

  if (!normalizedParent) {
    return !normalizedCandidate.includes("/");
  }

  if (!normalizedCandidate.startsWith(`${normalizedParent}/`)) {
    return false;
  }

  const remainder = normalizedCandidate.slice(normalizedParent.length + 1);
  return remainder.length > 0 && !remainder.includes("/");
}

export function stripLeadingSlash(path: string): string {
  return path.replace(LEADING_SLASHES, "");
}

export function stripTrailingSlash(path: string): string {
  return path.replace(TRAILING_SLASHES, "");
}

export function directoryPrefix(path: string): string {
  const normalized = normalizePath(path);
  return normalized ? `${normalized}/` : "";
}

export function toText(data: string | Uint8Array): string {
  if (typeof data === "string") {
    return data;
  }

  return new TextDecoder().decode(data);
}

export function toBytes(data: string | Uint8Array): Uint8Array {
  if (typeof data === "string") {
    return new TextEncoder().encode(data);
  }

  return data;
}
